/**
 * UNIFIED SERVICE WORKER
 * Handles both PWA Caching (via next-pwa) and Firebase Push Notifications.
 */

// 1. Import the default PWA service worker generated by next-pwa
importScripts('/sw.js');

// 2. Import Firebase Messaging scripts
importScripts('https://www.gstatic.com/firebasejs/10.7.0/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.7.0/firebase-messaging-compat.js');

// 3. Initialize Firebase in the Service Worker
// REPLACE THESE WITH YOUR ACTUAL CONFIG FROM FIREBASE CONSOLE
firebase.initializeApp({
  apiKey: "AIzaSyAogMOncvmZLqQ1qom0d3RDihdqOB9XRiY",
  authDomain: "studyscript.firebaseapp.com",
  projectId: "studyscript",
  storageBucket: "studyscript.firebasestorage.app",
  messagingSenderId: "891979418045",
  appId: "1:891979418045:web:047bfd8a00e148c14dead4"
});

const messaging = firebase.messaging();

/**
 * Handle background messages.
 * We use a data-only payload to have full control over the notification display.
 */
messaging.onBackgroundMessage((payload) => {
  console.log('[firebase-messaging-sw.js] Received background message ', payload);

  const notificationTitle = payload.data.title || "StudyScript Update";
  const notificationOptions = {
    body: payload.data.body || "You have a new update.",
    icon: '/icons/icon-192x192.png',
    badge: '/icons/icon-192x192.png',
    data: {
      url: payload.data.link || '/'
    }
  };

  self.registration.showNotification(notificationTitle, notificationOptions);
});

/**
 * Handle notification clicks to redirect users to the correct URL.
 */
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const targetUrl = event.notification.data.url || '/';

  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      // If a window is already open, focus it and navigate
      for (const client of clientList) {
        if (client.url === targetUrl && 'focus' in client) {
          return client.focus();
        }
      }
      // Otherwise, open a new window
      if (clients.openWindow) {
        return clients.openWindow(targetUrl);
      }
    })
  );
});
